import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "../App.css";

// 💡 아이콘을 위해 'react-icons' 라이브러리가 필요합니다.
// 터미널에서: npm install react-icons
import { FaRegLightbulb, FaRegClock } from "react-icons/fa6";
import { TfiInfinite } from "react-icons/tfi"; // 무한대 아이콘

function Hero() {
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();

  // --- 애니메이션 변형 ---
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.8, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
      },
    },
  };

  // --- 목업에 맞게 수정된 기능 데이터 ---
  const features = [
    {
      icon: FaRegLightbulb,
      title: "AI 자동 생성",
      description:
        "딥러닝 AI가 수수료율을 감안한 맞춤형 인테리어를 제안합니다.",
    },
    {
      icon: FaRegClock,
      title: "빠른 디자인", // '디디앙' 오타 수정
      description:
        "딥러닝에 의한 시공/견적 필요요소 심층분석, 비스포크적 무드로 리모델링 시안 확인",
    },
    {
      icon: TfiInfinite,
      title: "무한한 아이디어",
      description:
        "딥러닝에 의한 시공 수용률 예측, 최적화된 시그니처 시안 생성",
    },
  ];

  return (
    // 메인 컨테이너를 흰색 배경으로 변경
    <main style={{ background: "#fff", minHeight: "100vh" }}>
      {/* 1. 히어로 섹션 (Hero Section) */}
      <motion.div
        style={{
          maxWidth: "1200px",
          width: "100%",
          margin: "0 auto",
          padding: "0 20px",
        }}
        initial="hidden"
        animate="visible"
        variants={staggerContainer}
      >
        <section
          style={{
            display: "flex",
            alignItems: "center",
            gap: "40px",
            padding: "80px 0",
            flexWrap: "wrap", // 반응형을 위해 추가
          }}
        >
          {/* 왼쪽: 텍스트 및 CTA 버튼 */}
          <motion.div
            style={{ flex: "1 1 500px" }} // 반응형 flex-basis
            variants={fadeUp}
          >
            <h1
              style={{
                fontSize: "clamp(2.5rem, 5vw, 3.5rem)",
                fontWeight: 700,
                color: "#222", // 어두운 텍스트 색상
                marginBottom: "25px",
                lineHeight: "1.3",
              }}
            >
              AI-driven Interior
              <br />
              Proposals in Minutes
            </h1>
            <p
              style={{
                fontSize: "clamp(1rem, 2vw, 1.1rem)",
                color: "#555", // 어두운 텍스트 색상
                marginBottom: "40px",
                maxWidth: "500px",
                lineHeight: "1.7",
              }}
            >
              ASSEMBLE은 한샘 디자이너의 니즈에 맞게
              <br />
              AI 피팅 인테리어를 신속히 제안합니다.
            </p>

            <motion.div
              style={{
                display: "flex",
                gap: "20px",
                alignItems: "center",
              }}
              variants={fadeUp}
            >
              {/* 주황색 Get Started 버튼 */}
              <motion.button
                onClick={() => navigate(isAuthenticated ? "/projects" : "/login")}
                style={{
                  padding: "15px 35px",
                  fontSize: "1rem",
                  fontWeight: 700,
                  border: "none",
                  borderRadius: "8px",
                  background: "#f97316", // 목업의 주황색
                  color: "#fff",
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                }}
                whileHover={{ scale: 1.05, filter: "brightness(1.1)" }}
                whileTap={{ scale: 0.95 }}
              >
                Get Started
              </motion.button>

              {/* Learn More 텍스트 버튼 */}
              <motion.button
                onClick={() => navigate("/about")}
                style={{
                  padding: "15px 20px",
                  fontSize: "1rem",
                  fontWeight: 600,
                  border: "none",
                  background: "transparent",
                  color: "#555", // 어두운 텍스트 색상
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                }}
                whileHover={{ scale: 1.05, color: "#000" }}
                whileTap={{ scale: 0.95 }}
              >
                Learn More
              </motion.button>
            </motion.div>
          </motion.div>

          {/* 오른쪽: 이미지 */}
          <motion.div
            style={{
              flex: "1 1 400px", // 반응형 flex-basis
              height: "450px",
              borderRadius: "15px",
              overflow: "hidden",
              boxShadow: "0 15px 30px rgba(0,0,0,0.1)",
            }}
            variants={fadeUp}
          >
            <img
              // 목업과 유사한 한샘 키친 이미지 URL로 교체
              src="https://image.hanssem.com/hsimg/upload/m/main/2023/12/04/1701655078512_0.jpg"
              alt="Modern Kitchen Interior"
              style={{ width: "100%", height: "100%", objectFit: "cover" }}
            />
          </motion.div>
        </section>
      </motion.div>

      {/* 2. 기능 소개 섹션 (Features Section) */}
      <section style={{ background: "#f9f9f9", padding: "80px 0" }}>
        <motion.div
          style={{
            maxWidth: "1200px",
            width: "100%",
            margin: "0 auto",
            padding: "0 20px",
          }}
          initial="hidden"
          animate="visible"
          variants={staggerContainer}
        >
          {/* 섹션 소제목 */}
          <motion.h2
            style={{
              textAlign: "center",
              fontSize: "2rem",
              fontWeight: 600,
              color: "#333",
              marginBottom: "50px",
            }}
            variants={fadeUp}
          >
            디자이너를 위한 혁신적인 기능
          </motion.h2>

          {/* 기능 카드 그리드 */}
          <motion.div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
              gap: "30px",
            }}
            variants={staggerContainer}
          >
            {features.map((feature, index) => (
              <motion.div
                key={index}
                style={{
                  background: "#ffffff", // 흰색 카드
                  padding: "40px 30px",
                  borderRadius: "15px",
                  textAlign: "center",
                  boxShadow: "0 10px 30px rgba(0, 0, 0, 0.05)", // 부드러운 그림자
                  border: "1px solid #eee",
                }}
                variants={fadeUp}
                whileHover={{
                  y: -10,
                  boxShadow: "0 15px 35px rgba(0, 0, 0, 0.1)",
                  transition: { duration: 0.3 },
                }}
              >
                {/* 아이콘 렌더링 */}
                <feature.icon
                  style={{
                    fontSize: "3rem",
                    color: "#f97316", // 주황색 아이콘
                    marginBottom: "25px",
                  }}
                />

                <h3
                  style={{
                    fontSize: "1.4rem",
                    fontWeight: 600,
                    color: "#333",
                    marginBottom: "15px",
                  }}
                >
                  {feature.title}
                </h3>
                <p
                  style={{
                    fontSize: "0.95rem",
                    color: "#666",
                    lineHeight: "1.6",
                    margin: 0,
                  }}
                >
                  {feature.description}
                </p>
              </motion.div>
            ))}
          </motion.div>
        </motion.div>
      </section>
    </main>
  );
}

export default Hero;
